code.cpp:
class Solution {
public:
    bool checkPartitioning(string s) {
        int n = s.size();
        string t(2 * n + 1, '#');
        for (int i = 0; i < n; i++) t[2 * i + 1] = s[i];
        int m = t.size();
        vector<int> rad(m, 0);
        int c = 0, rgt = 0;
        for (int i = 0; i < m; i++) {
            if (i < rgt) {
                int mir = 2 * c - i;
                rad[i] = min(rgt - i, rad[mir]);
            }
            while (i + rad[i] + 1 < m && i - rad[i] - 1 >= 0 &&
                   t[i + rad[i] + 1] == t[i - rad[i] - 1]) {
                rad[i]++;
            }
            if (i + rad[i] > rgt) {
                c = i;
                rgt = i + rad[i];
            }
        }
        auto isPal = [&](int l, int rr) -> bool {
            return rad[l + rr + 1] >= rr - l;
        };
        for (int i = 0; i <= n - 3; i++) {
            if (!isPal(0, i)) continue;
            for (int j = i + 1; j <= n - 2; j++) {
                if (isPal(i + 1, j) && isPal(j + 1, n - 1)) return true;
            }
        }
        return false;
    }
};
